const JobsFeature={id:"jobs",name:"Jobs",icon:"construction",route:!1,STAGES:[["materials_ordered","Materials ordered","inventory_2"],["materials_received","Materials received","inventory"],["fitting_scheduled","Fitting scheduled","event"],["on_site","On site","home_repair_service"],["blocked","Blocked","warning"],["return_visit_required","Return required","assignment_return"],["completed","Completed","task_alt"],["signed_off","Signed off","verified"]],render(e={}){return e.id?this.renderJob(Number(e.id)):this.renderList(e)},stageMeta(e){const t=this.STAGES.find(t=>t[0]===e)||this.STAGES[0];return{id:t[0],label:t[1],icon:t[2]}},async renderList(e={}){const t=Number(e.orderId)||null,s=Number(e.customerId)||null;let a=[];try{a=await DB.getJobs({...t?{orderId:t}:{},...s?{customerId:s}:{}})}catch(e){console.error("Jobs load failed:",e)}return`<div class="fade-in">\n      ${App.renderTopHeader({title:t?"Order jobs":"Jobs",showBack:!0,backHref:t?`orders?id=${t}`:"control",actions:t?`<button class="btn btn-sm btn-primary" data-action="JobsFeature.createFromOrder" data-args='${JSON.stringify([t])}'><span class="material-symbols-rounded">add</span>Job</button>`:""})}\n      <div class="px-md pb-lg">\n        ${a.length?a.map(e=>this.renderJobCard(e)).join(""):`<div class="empty-state empty-state-lg"><span class="material-symbols-rounded">construction</span><div class="fw-600">No jobs yet</div><div class="fs-13">Create a job from an order when operational work begins.</div>${t?`<button class="btn btn-primary btn-sm mt-md" data-action="JobsFeature.createFromOrder" data-args='${JSON.stringify([t])}'>Create job</button>`:""}</div>`}\n        ${t&&a.length?'<div class="hint mt-md">An order can have more than one job. Use + Job only when the work genuinely needs a separate operational record.</div>':""}\n      </div>\n    </div>`},renderJobCard(e){const t=this.stageMeta(e.status);return`<button class="card mb-sm w-full text-left" data-action="App.navigate" data-args='${JSON.stringify(["jobs",{id:e.id}])}'>\n      <div class="flex justify-between gap-sm"><strong>${Utils.escapeHtml(e.jobNumber||`Job ${e.id}`)}</strong><span class="badge"><span class="material-symbols-rounded fs-14">${t.icon}</span>${Utils.escapeHtml(t.label)}</span></div>\n      ${e.summary?`<div class="fs-13 text-secondary mt-6">${Utils.escapeHtml(e.summary)}</div>`:""}\n    </button>`},async createFromOrder(e){if(!this._creating){this._creating=!0;try{const t=`job:${e}:${Date.now()}`,s=await DB.createJobFromOrder(e,{},t);Toast.show(s.created?"Job created":"Job already created","success"),App.navigate("jobs",{id:s.job.id})}catch(e){console.error("Create job failed:",e),Toast.show("Could not create job","error")}finally{this._creating=!1}}},async renderJob(e){const t=await DB.getJob(e);if(!t)return'<div class="empty-state"><span class="material-symbols-rounded">error</span><div>Job not found</div></div>';const s=await DB.getJobAppointments(e);let a=null;try{"undefined"!=typeof JobFieldService&&(a=await JobFieldService.load(e))}catch(e){console.error("Job field workspace failed:",e)}let n=null;try{t.customerId&&(n=await DB.getCustomer(t.customerId))}catch(e){}const i=this.stageMeta(t.status),r=n?.fullName||[n?.firstName,n?.lastName].filter(Boolean).join(" ")||"Customer";return`<div class="fade-in">\n      ${App.renderTopHeader({title:t.jobNumber||`Job ${t.id}`,showBack:!0,backHref:t.orderId?`jobs?orderId=${t.orderId}`:"jobs"})}\n      <div class="p-md">\n        <div class="card card-page"><div class="flex justify-between gap-sm"><div><strong>${Utils.escapeHtml(r)}</strong><div class="fs-12 text-tertiary">${t.orderId?`Order linked · ${s.length} visit${1===s.length?"":"s"}`:`${s.length} linked visits`}</div></div><span class="badge"><span class="material-symbols-rounded fs-14">${i.icon}</span>${Utils.escapeHtml(i.label)}</span></div></div>\n\n        <div class="card card-page"><div class="section-label">Operational stage</div><div class="grid-2 gap-sm">${this.STAGES.filter(([e])=>!["completed","signed_off"].includes(e)).map(([e,s,a])=>`<button class="btn ${t.status===e?"btn-primary":"btn-outline"} btn-sm" data-action="JobsFeature.transition" data-args='${JSON.stringify([t.id,e])}' aria-pressed="${t.status===e}"><span class="material-symbols-rounded fs-16">${a}</span>${Utils.escapeHtml(s)}</button>`).join("")}</div><div class="hint mt-sm">Completion and customer sign-off use the checked actions below; they do not change payment status.</div></div>\n\n        <div class="card card-page"><div class="flex items-center justify-between mb-sm"><div class="section-label mb-0">Visits</div><button class="btn btn-outline btn-sm" data-action="JobsFeature.openSchedule" data-args='${JSON.stringify([t.id])}'><span class="material-symbols-rounded">add</span>Schedule</button></div>\n          ${s.length?s.map(e=>`<button class="area-customer-row w-full text-left mb-6" data-action="App.navigate" data-args='${JSON.stringify(["appointments",{id:e.id}])}'><span class="material-symbols-rounded">${"fitting"===e.type?"handyman":"service_call"===e.type?"build":"event"}</span><span class="flex-1"><strong>${Utils.escapeHtml(CONFIG.appointmentTypes.find(t=>t.id===e.type)?.name||e.type||"Visit")}</strong><small>${Utils.formatDate(e.date,"short")} · ${e.arrivalStart&&e.arrivalEnd?`${e.arrivalStart}–${e.arrivalEnd}`:Utils.formatTime(e.date)}</small></span><span class="material-symbols-rounded">chevron_right</span></button>`).join(""):'<div class="fs-13 text-tertiary">No fitting, service or return visits linked yet.</div>'}\n        </div>\n\n        ${a?JobFieldService.render(a):""}\n        <div class="grid-2 gap-sm">\n          ${t.orderId?`<button class="btn btn-outline btn-sm" data-action="OrdersFeature.openOrderSheet" data-args='${JSON.stringify([t.orderId])}'><span class="material-symbols-rounded">receipt</span>Order</button>`:""}\n          <button class="btn btn-outline btn-sm" data-action="ProfitabilityFeature.openJob" data-args='${JSON.stringify([t.id])}'><span class="material-symbols-rounded">monitoring</span>Profitability</button>\n          <button class="btn btn-outline btn-sm" data-action="App.navigate" data-args='${JSON.stringify(["suppliers",{jobId:t.id,orderId:t.orderId}])}'><span class="material-symbols-rounded">local_shipping</span>Supplier orders</button>\n          ${t.customerId?`<button class="btn btn-outline btn-sm" data-action="App.navigate" data-args='${JSON.stringify(["retention",{customerId:t.customerId,jobId:t.id,orderId:t.orderId}])}'><span class="material-symbols-rounded">handshake</span>Aftercare</button>`:""}\n          ${t.customerId?`<button class="btn btn-outline btn-sm" data-action="App.navigate" data-args='${JSON.stringify(["customer",{id:t.customerId}])}'><span class="material-symbols-rounded">person</span>Customer 360</button>`:""}\n        </div>\n      </div>\n    </div>`},async transition(e,t){if(!this.STAGES.some(e=>e[0]===t))return Toast.show("Unknown job stage","error");try{await DB.setJobStage(e,t,{changedAt:(new Date).toISOString()}),Toast.show(`Job moved to ${this.stageMeta(t).label}`,"success"),App.navigate("jobs",{id:e})}catch(e){console.error("Job transition failed:",e),Toast.show("Could not update job","error")}},openSchedule(e){App.openModal(`<div class="sheet-handle"></div><div class="sheet-header"><h3>Schedule job visit</h3><button class="btn btn-ghost btn-sm" data-action="App.closeModal" aria-label="Close"><span class="material-symbols-rounded">close</span></button></div><div class="sheet-body">\n      <button class="btn btn-outline btn-block" data-close="1" data-action="JobsFeature.scheduleVisit" data-args='${JSON.stringify([e,"fitting","fitting"])}'><span class="material-symbols-rounded">handyman</span>Fitting</button>\n      <button class="btn btn-outline btn-block mt-sm" data-close="1" data-action="JobsFeature.scheduleVisit" data-args='${JSON.stringify([e,"service_call","service"])}'><span class="material-symbols-rounded">build</span>Service call</button>\n      <button class="btn btn-outline btn-block mt-sm" data-close="1" data-action="JobsFeature.scheduleVisit" data-args='${JSON.stringify([e,"service_call","return_visit"])}'><span class="material-symbols-rounded">assignment_return</span>Return visit</button>\n    </div>`)},scheduleVisit(e,t,s=t){App.closeModal(),App.navigate("appointments",{action:"add",jobId:e,type:t,jobRole:s})},setChecklistItem:(...e)=>JobFieldService.setChecklistItem(...e),openAddIssue:e=>JobFieldService.openAddIssue(e),saveIssue:e=>JobFieldService.saveIssue(e),openResolveIssue:(e,t)=>JobFieldService.openResolveIssue(e,t),resolveIssue:(e,t)=>JobFieldService.resolveIssue(e,t),openCompleteJob:e=>JobFieldService.openComplete(e),confirmCompleteJob:e=>JobFieldService.confirmComplete(e),openSignOff:e=>JobFieldService.openSignOff(e),confirmSignOff:e=>JobFieldService.confirmSignOff(e)};App.registerFeature(JobsFeature);
